import{z as n,x as o,o as t,c as d,q as B,j as A,D as r,d as e,s as i,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"代码验证器：单元测试","description":"","frontmatter":{"title":"代码验证器：单元测试","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/code-verifier-unittests.md","filePath":"llm/code-verifier-unittests.md","lastUpdated":1791413859000}'),p={name:"llm/code-verifier-unittests.md"};function m(h,a,u,c,f,R){const l=o("Mermaid");return t(),d("div",null,[a[2]||(a[2]=B('<h1 id="代码验证器-单元测试" tabindex="-1">代码验证器：单元测试 <a class="header-anchor" href="#代码验证器-单元测试" aria-label="Permalink to &quot;代码验证器：单元测试&quot;">​</a></h1><div class="epigraph"><p>通过率是程序给的，不是裁判给的；奖励通道上只应留下可复现的沙箱结果。</p><footer>—— 对照 HumanEval / MBPP 的单测传统；CodeRL、DeepSeek-R1 把编译与测试接到策略梯度</footer></div><p><a href="/llm/rubric-reward">上一课</a>把质量拆成条目，其中「程序是否做对」仍可能交给 LLM 裁判。缺口是：代码域存在真正的 <a href="/llm/verifiable-reward">可验证奖励</a>——<strong>单元测试与编译器。</strong> 本课把 \\(R\\) 写成沙箱里的通过率。Le 等人的 CodeRL、竞赛编程流水线、R1 的代码奖励，都走这条通道。后课数学验证器是另一类程序判定，不要混进单测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代码生成的「看起来对」极廉价：类型名像那么回事、注释写得很自信。标量 RM 与 LLM 裁判都吃这一套。单测把事件钉死：给定输入，输出是否等于期望、是否在时限与内存内、是否允许网络。\\(R\\) 可以是 0/1（全过）或通过率。策略梯度要的就是这个可批量调用的函数。</p><p>噪声来自规范，不是来自网络：公开测例覆盖不足会把错误实现标成对；浮点与并发会让同一 \\(y\\) 的 \\(R\\) 抖动。HumanEval 原协议是隐藏测例；训练若只用公开用例，RL 会硬编码输出。</p><p><span class="marginnote">「硬编码」指模型不写通用算法，而是背下样例的输入输出、把答案直接写死在代码里。看似通过测试，其实什么都没学到。RL 会放大这类漏洞：哪里奖励高，策略就往哪里钻，所以训练测例必须比模型能「背」的范围更广。</span></p><h3 id="抽取与运行是-的一部分" tabindex="-1">抽取与运行是 \\(R\\) 的一部分 <a class="header-anchor" href="#抽取与运行是-的一部分" aria-label="Permalink to &quot;抽取与运行是 $R$ 的一部分&quot;">​</a></h3><p>模型常常把代码包在 Markdown 或解释里。extract 失败则 \\(R=0\\) 或 mask，二者对格式的压力不同，见可验证奖励课。运行规范：镜像、超时、是否联网、是否可写磁盘，必须版本化。副作用会让奖励不可复现，<a href="/llm/ppo-llm">PPO</a> 的优势变成噪声。</p><p><span class="marginnote">不要把「用 GPT-4 读代码打分」叫做本课的验证器。那是上一课的裁判。本课的动词是执行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个题 \\(x\\) 采 \\(G\\) 条完成（<a href="/llm/grpo">GRPO</a> 组采样天然合适），抽代码，在沙箱跑测试集 \\(\\mathcal{T}\\)：</p> \\[R(x,y)=\\frac1{|\\mathcal{T}|}\\sum_{t\\in\\mathcal{T}}\\mathbf{1}\\{\\mathrm{exec}(y,t)=\\mathrm{ok}\\}. \\]<p>隐藏测例只用于金标，不进训练 \\(R\\)，否则过优化测例洞无法被发现。编译失败、超时、抽取失败单独记账，不要与逻辑错误混成一个桶。优势用组内基线；全 0 / 全 1 组无梯度，留给后课动态采样。</p>',14)),(t(),A(s,null,{default:r(()=>[i(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E7%94%9F%E6%88%90%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20EX%5B%22%E6%8A%BD%E5%8F%96%E6%BA%90%E7%A0%81%22%5D%0A%20%20EX%20--%3E%20SB%5B%22%E6%B2%99%E7%AE%B1%E6%89%A7%E8%A1%8C%E5%8D%95%E6%B5%8B%22%5D%0A%20%20SB%20--%3E%20R%5B%22%E9%80%9A%E8%BF%87%E7%8E%87%20R%22%5D%0A%20%20R%20--%3E%20ADV%5B%22%E7%BB%84%E5%86%85%E4%BC%98%E5%8A%BF%22%5D%0A%20%20ADV%20--%3E%20PI%5B%22%E6%9B%B4%E6%96%B0%E7%AD%96%E7%95%A5%22%5D%0A%20%20HID%5B%22%E9%9A%90%E8%97%8F%E6%B5%8B%E4%BE%8B%22%5D%20--%3E%20GOLD%5B%22%E9%87%91%E6%A0%87%EF%BC%8C%E4%B8%8D%E8%BF%9B%E8%AE%AD%E7%BB%83%20R%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("与 "),E("a",{href:"/llm/process-supervision"},"过程监督"),e(" 不同：单测是结果信号，中间错误但测例碰巧过仍得高 \\(R\\)。要逐步质量，需另加 PRM 或静态检查，不要假装通过率等于过程正确。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"通过率比 0/1 密：部分测例提供部分信用，方差低于「全过才给 1」。但部分分会鼓励「写一个总能过样例的硬编码」。测例要含边界与随机化输入。时限把复杂度写进 \\(R\\)：算法对但常数大，会被判错——这是环境定义，应在题面声明。",-1)),(t(),A(s,null,{default:r(()=>[i(l,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20BIN%5B%220%2F1%20%E5%A5%96%E5%8A%B1%EF%BC%9A%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%E6%89%8D%E7%BB%99%201%22%5D%0A%20%20%20%20B1%5B%22%E4%BF%A1%E5%8F%B7%E7%A8%80%20%C2%B7%20%E6%96%B9%E5%B7%AE%E5%A4%A7%22%5D%20--%3E%20B2%5B%22%E9%9A%BE%E4%BB%A5%E8%A2%AB%E6%A0%B7%E4%BE%8B%E7%A1%AC%E7%BC%96%E7%A0%81%E9%AA%97%E8%BF%87%22%5D%0A%20%20end%0A%20%20subgraph%20PART%5B%22%E9%80%9A%E8%BF%87%E7%8E%87%E5%A5%96%E5%8A%B1%EF%BC%9A%E9%83%A8%E5%88%86%E4%BF%A1%E7%94%A8%22%5D%0A%20%20%20%20P1%5B%22%E4%BF%A1%E5%8F%B7%E5%AF%86%20%C2%B7%20%E6%96%B9%E5%B7%AE%E5%B0%8F%22%5D%20--%3E%20P2%5B%22%E6%98%93%E8%AF%B1%E5%AF%BC%E5%8F%AA%E8%BF%87%E6%A0%B7%E4%BE%8B%E7%9A%84%E7%A1%AC%E7%BC%96%E7%A0%81%22%5D%0A%20%20end%0A%20%20BIN%20--%3E%20FIX%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9A%E8%BE%B9%E7%95%8C%E7%94%A8%E4%BE%8B%20%2B%20%E9%9A%8F%E6%9C%BA%E5%8C%96%E8%BE%93%E5%85%A5%20%2B%20%E9%9A%90%E8%97%8F%E6%B5%8B%E4%BE%8B%22%5D%0A%20%20PART%20--%3E%20FIX%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">时限如何把复杂度写进奖励，可以代个数：同一道题，\\(O(n\\log n)\\) 的解在 \\(n=10^6\\) 时约两千万次运算，几十毫秒跑完；\\(O(n^2)\\) 要 \\(10^{12}\\) 次，几分钟都出不来，直接超时判零。「算法对但太慢」，在单测世界里就是错。</span></p><p><span class="marginnote">沙箱吞吐决定 RL 墙钟。数学正则便宜几个数量级；代码 batch 要按环境分组，避免数学 step 等超时。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有单测的开放编程题不属于本课，应退回细则或裁判。代理式修仓库（SWE）的环境更重，留到后课 SWE-RL。单测 \\(R\\) 仍会过优化公开用例：保留隐藏集与人工抽查。下一课把「答案相等」从字符串匹配升级到数学等价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代码奖励是沙箱通过率，抽取与运行规范属于 \\(R\\)。</li><li>隐藏测例只做金标；训练用例会被硬编码。</li><li>组采样 + 相对优势适合 0/1 或通过率；全对全错组无梯度。</li><li>通过率不是过程正确；需要逐步信号时另接 PRM。</li><li>出处：Chen 等 HumanEval；Austin 等 MBPP；Le 等 CodeRL；R1 的代码可验证奖励。</li></ul>',6))])}const P=n(p,[["render",m]]);export{F as __pageData,P as default};
